const vals = wb.getRange('Sheet1!A1:A5000').getValues().map(r=>r[0]);
const norm = vals.filter(v=>v!==null&&v!==undefined&&v!=='').map(v=>String(v));
const set = new Set(norm);
const lens={}; norm.forEach(w=>lens[w.length]=(lens[w.length]||0)+1);
const ends=['ING','ERS','ATE','EST','ONE','IER','ILY'];
const endC={}; norm.forEach(w=>{const e=w.slice(-3); endC[e]=(endC[e]||0)+1});
const top=Object.entries(endC).sort((a,b)=>b[1]-a[1]).slice(0,15);
const pairs=[];
norm.forEach((w,i)=>{const t=w[4]+w.slice(0,4)+w.slice(5); if(set.has(t)) pairs.push([i+1,w,t])});
const byEnd={}; pairs.forEach(p=>{const e=p[1].slice(-3); (byEnd[e]=byEnd[e]||[]).push(p)});
const odd=norm.filter(w=>w!==w.trim()||/[^A-Z]/.test(w)).slice(0,10);
({n:norm.length,distinct:set.size,lens,top,odd,pairsN:pairs.length,selfPairs:pairs.filter(p=>p[1]===p[2]).length,byEndCounts:Object.fromEntries(Object.entries(byEnd).map(([k,v])=>[k,v.length])),byEnd:byEnd,earth:set.has('EARTHPEA'),heart:set.has('HEARTPEA'),blankIdx:vals.findIndex(v=>v===null||v===''),sorted:norm.every((w,i)=>i==0||norm[i-1]<=w)})

