const norm = wb.getRange('Sheet1!A1:A5000').getValues().map(r=>String(r[0]));
const set = new Set(norm);
const ends=['ING','ERS','ATE','EST','ONE','IER','ILY'];
const pairs=[];
for (const w of norm){const t=w[4]+w.slice(0,4)+w.slice(5); if(set.has(t)) pairs.push([t,w]);}
pairs.sort((a,b)=> ends.indexOf(a[1].slice(-3))-ends.indexOf(b[1].slice(-3)) || (a[1]<b[1]?-1:1));
wb.getRange('Sheet1!C2:D'+(pairs.length+1)).setValues(pairs.map(p=>["'"+p[0],"'"+p[1]]));
log(pairs.length, pairs.some(p=>ends.indexOf(p[1].slice(-3))<0));
