log(a.join('|')===norm.join('|'), wb.getRange('Sheet1!C1:D1').getValues());
log(wb.getRange('Sheet1!C1:D15'));
log(wb.getRange('Sheet1!C2:D5000').getCounts());
log(wb.getRange('Sheet1!C2').getCell());

